    // Track the drag marker outside the React layout so the game UI never reflows.
    (function () {
      var indicator = document.getElementById('paint-drag-indicator');
      var activePointerId = null;
      var colors = {
        red: '#dc2828',
        yellow: '#f0c828',
        blue: '#2850dc',
        white: '#f4f4f4',
        black: '#282828'
      };

      function moveIndicator(event) {
        indicator.style.transform = 'translate3d(' + (event.clientX - 24) + 'px,' + (event.clientY - 24) + 'px,0)';
      }

      function endIndicator(event) {
        if (activePointerId === null || (event.pointerId != null && event.pointerId !== activePointerId)) return;
        indicator.style.opacity = '0';
        indicator.style.visibility = 'hidden';
        activePointerId = null;
      }

      document.addEventListener('touchmove', function (event) {
        event.preventDefault();
      }, { passive: false });
      document.addEventListener('pointerdown', function (event) {
        var tube = event.target.closest && event.target.closest('img[src*="tube_"]');
        if (!tube) return;
        event.preventDefault();
        activePointerId = event.pointerId;
        indicator.style.background = colors[(tube.alt || '').toLowerCase()] || '#ffffff';
        indicator.style.opacity = '1';
        indicator.style.visibility = 'visible';
        moveIndicator(event);
      }, { capture: true, passive: false });
      document.addEventListener('pointermove', function (event) {
        if (event.pointerId !== activePointerId) return;
        event.preventDefault();
        moveIndicator(event);
      }, { capture: true, passive: false });
      document.addEventListener('pointerup', endIndicator, { capture: true });
      document.addEventListener('pointercancel', endIndicator, { capture: true });
      document.addEventListener('lostpointercapture', endIndicator, { capture: true });
      window.addEventListener('blur', function () { endIndicator({}); });
    }());
  
